const cfg = $('Config').first().json;
const targets = $('Target Pages').all();
const inputs = $input.all();

// Tiered. Best available tier per company wins, so one company gets at most one mail.
const TIERS = [
  ['careers', /^(jobs|job|karriere|careers|career|bewerbung|bewerbungen|recruiting|recruitment|hiring|join|apply)@/i],
  ['people',  /^(hr|people|talent|personal|personalabteilung|team)@/i],
  ['general', /^(info|kontakt|contact|hello|hallo|office|mail|anfrage|welcome)@/i]
];
// Wrong desk or legally sensitive - never mailed regardless of tier settings.
const NEVER = /^(noreply|no-reply|donotreply|postmaster|abuse|support|sales|vertrieb|presse|press|media|datenschutz|privacy|legal|impressum|billing|invoice|accounting|webmaster|admin)@/i;
const JUNK = /(noreply|example\.|\.png|\.jpg|wixpress|sentry)/i;
const MAILTO = /mailto:([A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,24})/gi;

const allowed = new Set(cfg.addressTiers || ['careers']);
const best = new Map();   // company -> {meta, email, tier, rank}

for (let i = 0; i < inputs.length; i++) {
  const meta = (targets[i] || {}).json || {};
  if (!meta.name) continue;
  const body = typeof inputs[i].json === 'string' ? inputs[i].json
             : (inputs[i].json.data || inputs[i].json.body || '');
  if (!body || typeof body !== 'string') continue;

  const dom = String(meta.domain || '').replace(/^www\./, '');
  const root = dom.split('.').slice(-2).join('.');

  let m; MAILTO.lastIndex = 0;
  while ((m = MAILTO.exec(body)) !== null) {
    const e = m[1].toLowerCase();
    if (JUNK.test(e) || NEVER.test(e)) continue;
    // Must belong to the company whose page we fetched, not a third party linked on it.
    if (!(e.endsWith('@' + dom) || e.endsWith('@' + root) || e.endsWith('.' + root))) continue;

    const idx = TIERS.findIndex(([, rx]) => rx.test(e));
    if (idx < 0) continue;
    const [tier] = TIERS[idx];
    if (!allowed.has(tier)) continue;

    const prev = best.get(meta.name);
    if (!prev || idx < prev.rank) {
      best.set(meta.name, { ...meta, contactEmail: e, tier, rank: idx, foundOn: meta.url });
    }
  }
}

// Harvest what the company says about itself from the SAME pages - no extra requests.
const txt = v => String(v || '').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&').replace(/&#(\d+);/g, (mm, dd) => String.fromCharCode(+dd))
  .replace(/\s+/g, ' ').trim();
const profile = new Map();
for (let i = 0; i < inputs.length; i++) {
  const meta = (targets[i] || {}).json || {};
  if (!meta.name || !best.has(meta.name)) continue;
  const body = typeof inputs[i].json === 'string' ? inputs[i].json
             : (inputs[i].json.data || inputs[i].json.body || '');
  if (!body || typeof body !== 'string') continue;
  const bits = [];
  const t = body.match(/<title[^>]*>([\s\S]{0,200}?)<\/title>/i);
  if (t) bits.push(txt(t[1]));
  const d = body.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']{0,300})["']/i)
        || body.match(/<meta[^>]+content=["']([^"']{0,300})["'][^>]+name=["']description["']/i);
  if (d) bits.push(txt(d[1]));
  for (const h of (body.match(/<h[12][^>]*>([\s\S]{0,160}?)<\/h[12]>/gi) || []).slice(0, 6)) {
    const c = txt(h); if (c.length > 12) bits.push(c);
  }
  profile.set(meta.name, (profile.get(meta.name) || []).concat(bits));
}
return [...best.values()].map(v => ({ json: {
  ...v, profileText: [...new Set(profile.get(v.name) || [])].join(' | ').slice(0, 900)
} }));

